const int MODUL = 1000000007;
int p_value, k_value, total, visited_state[1 << 20];

int compute_result() {
    total = 1;
    if (k_value == 0) {
        for (int i = 1; i < p_value; ++i) {
            total = (long long)total * p_value % MODUL;
        }
    } else if (k_value == 1) {
        for (int i = 1; i <= p_value; ++i) {
            total = (long long)total * p_value % MODUL;
        }
    } else {
        for (int i = 0; i < p_value; ++i) {
