                int current_idx = i;
                while (!visited_state[current_idx]) {
                    visited_state[current_idx] = 1;
                    ++cycle_len;
                    current_idx = (long long)current_idx * k_value % p_value;
                }
                if (current_idx != 0) {
                    total = (long long)total * p_value % MODUL;
                }
            }
        }
    }
    return total;
}

