p_value, k_value = map(int, input().split())

MODUL = 1000000007
visited_state = [0] * (1 << 20)

def compute_result():
    total = 1
    if k_value == 0:
        for i in range(1, p_value):
            total = (total * p_value) % MODUL
    elif k_value == 1:
        for i in range(1, p_value + 1):
            total = (total * p_value) % MODUL
    else:
        for i in range(p_value):
            if not visited_state[i]:
                cycle_len = 0
                current_idx = i
                while not visited_state[current_idx]:
                    visited_state[current_idx] = 1
                    cycle_len += 1
                    current_idx = (current_idx * k_value) % p_value
                if current_idx != 0:
                    total = (total * p_value) % MODUL
    return total

